# Variant: reputation update uses different weights and a cap, and decide uses a threshold on recipient reputation.

def evaluate(current_reputation, observation, my_history, round_num):
    """
    Update reputation based on observed action.
    - Action 'A' is punished more heavily, especially for high reputations.
    - Action 'B' is rewarded, but reward decreases as reputation approaches 1.
    - Reputation is clamped to [-1.0, 1.0].
    """
    if observation['action'] == 'A':
        # Punish defection more if reputation is already high, less if low
        penalty = 0.2 if current_reputation > 0 else 0.1
        return max(-1.0, current_reputation - penalty)
    else:  # action 'B'
        # Reward cooperation, but reward diminishes near top
        if current_reputation >= 0.9:
            reward = 0.0
        elif current_reputation >= 0.5:
            reward = 0.05
        else:
            reward = 0.15
        return min(1.0, current_reputation + reward)

def decide(recipient_reputation, round_num, my_history):
    """
    Choose action based on recipient's reputation.
    If reputation > threshold, cooperate (assumed action B = False).
    Initially more tolerant, becomes stricter over time.
    """
    # Threshold starts low and increases: early rounds exploit, later rounds conditionally cooperate
    threshold = 0.2 + 0.05 * round_num
    return recipient_reputation > threshold  # True -> A, False -> B (assuming B is cooperative)

